double next_double(unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    seed = (a * seed + c) % m;
    return (double)seed / m;
}

double gaussian_box_muller(double mean, double sigma, unsigned int& seed, unsigned int a, unsigned int c, unsigned int m) {
    double u1 = next_double(seed, a, c, m);
    while (u1 <= 0) u1 = next_double(seed, a, c, m);
    double u2 = next_double(seed, a, c, m);
    double r = std::sqrt(-2 * std::log(u1));
    double theta = 2 * M_PI * u2;
    double gaussian1 = mean + sigma * r * std::cos(theta);
    return gaussian1;
}
